#!/usr/bin/env python3
# Blackout-Radar Fehlalarm-Daempfung. Kein Mesh.
from __future__ import annotations
import base64, hashlib, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
DATEI = "blackout_radar.py"
ALT = ("4ff38da718afed9d", 84127)

def load():
    roh = PAYLOAD_JSON["pairs"][DATEI]
    return [(base64.b64decode(x["old"]), base64.b64decode(x["new"])) for x in roh]

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    m = jetzt.minute
    return 5 <= m <= 39, "Berlin Minute %02d" % m

def verwandle(data, pairs):
    if all(data.count(neu) == 1 and data.count(old) == 0 for old, neu in pairs):
        return data
    neu_data = data
    for old, neu in pairs:
        if neu_data.count(neu) == 1 and neu_data.count(old) == 0:
            continue
        if neu_data.count(old) != 1 or neu_data.count(neu) != 0:
            raise RuntimeError("Stelle")
        vor = neu_data
        neu_data = neu_data.replace(old, neu, 1)
        if neu_data.replace(neu, b"", 1) != vor.replace(old, b"", 1):
            raise RuntimeError("ausserhalb")
    return neu_data

def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-radar6-*"))
    bak = path.with_name(path.name + ".bak-radar6-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass

def schreiben(path: Path, data: bytes):
    mode = path.stat().st_mode & 0o777
    tmp = path.with_name("." + path.name + ".tmp-radar6")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def apply_dir(ordner: Path, dry: bool, kein: bool, jetzt=None) -> int:
    paare = load()
    pfad = ordner / DATEI
    if pfad.is_symlink() or not pfad.is_file():
        print("STOP: %s fehlt" % DATEI)
        return 2
    data = pfad.read_bytes()
    ist = sha(data)
    print("%s sha16 %s bytes %d" % (DATEI, ist[:16], len(data)))
    ziel_bytes = paare[0][1]
    ziel_sha = sha(ziel_bytes)
    if ist == ziel_sha:
        print("bereits installiert, keine Aenderung, kein Neustart")
        print("endstand sha16 %s bytes %d" % (ziel_sha[:16], len(ziel_bytes)))
        return 0
    kopf, laenge = ALT
    if not ist.startswith(kopf) or len(data) != laenge:
        print("STOP: %s ist nicht die Basis" % ist[:16])
        return 2
    try:
        ziel = verwandle(data, paare)
    except RuntimeError:
        print("STOP: Stelle unbekannt")
        return 2
    compile(ziel, DATEI, "exec")
    if b"wackelt" not in ziel or b"2 * 3600" not in ziel:
        print("STOP: Daempfung fehlt")
        return 2
    print("endstand sha16 %s bytes %d" % (sha(ziel)[:16], len(ziel)))
    frei, meldung = fenster(jetzt)
    print(meldung)
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        print("Pruefung: curl -sS http://127.0.0.1:5000/api/blackout/radar")
        return 0
    if not frei:
        print("STOP: Neustart nur Minute 05-39 Berlin. Nichts geschrieben.")
        return 2
    try:
        sichern(pfad, data)
        schreiben(pfad, ziel)
    except (OSError, RuntimeError) as exc:
        print("STOP beim Schreiben: %s" % exc)
        return 3
    print("geschrieben. Drei Fehl-Scans, Zielname, 2 h je Stufe.")
    if kein:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Datei ist neu, der Neustart bleibt aus.")
        return 2
    __import__("subprocess").run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("Nur prepper-dashboard neu gestartet.")
    return 0

def selftest() -> int:
    assert fenster(datetime(2026, 11, 21, 12, 5))[0]
    assert fenster(datetime(2026, 11, 21, 12, 39))[0]
    assert not fenster(datetime(2026, 11, 21, 12, 4))[0]
    assert not fenster(datetime(2026, 11, 21, 12, 40))[0]
    paare = load()
    old, neu = paare[0]
    assert neu.count(old) == 0
    import tempfile
    ordner = Path(tempfile.mkdtemp(prefix="radar6-"))
    pfad = ordner / DATEI
    pfad.write_bytes(b"UNBERUEHRT")
    assert apply_dir(ordner, True, True, datetime(2026, 11, 21, 12, 12)) == 2
    assert pfad.read_bytes() == b"UNBERUEHRT"
    pfad.write_bytes(old)
    assert apply_dir(ordner, True, True, datetime(2026, 11, 21, 12, 12)) == 0
    assert pfad.read_bytes() == old
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 4)) == 2
    assert pfad.read_bytes() == old
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 12)) == 0
    assert pfad.read_bytes() == neu
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 12)) == 0
    pfad.write_bytes(b"ANDERES")
    assert apply_dir(ordner, False, True, datetime(2026, 11, 21, 12, 12)) == 2
    assert pfad.read_bytes() == b"ANDERES"
    print("selftest ok")
    return 0

def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)

PAYLOAD_JSON = {"pairs": {"blackout_radar.py": [{"old": "", "new": ""}]}}

if __name__ == "__main__":
    sys.exit(main(sys.argv))
